<?php
require_once __DIR__.'/../includes/init.php';require_admin();$admin=current_user();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'');if($id===(int)$admin['id'])flash('danger','You cannot block your own admin account.');elseif(in_array($status,['active','blocked'],true)){db()->prepare('UPDATE users SET status=? WHERE id=? AND role<>\'admin\'')->execute([$status,$id]);flash('success','User status updated.');}redirect('admin/users.php');}
$q=trim((string)($_GET['q']??''));if($q!==''){$like='%'.$q.'%';$stmt=db()->prepare('SELECT * FROM users WHERE name LIKE ? OR email LIKE ? ORDER BY created_at DESC');$stmt->execute([$like,$like]);}else{$stmt=db()->query('SELECT * FROM users ORDER BY created_at DESC');}$users=$stmt->fetchAll();$pageTitle='Admin Users - Campus Connect';include __DIR__.'/_admin_header.php';
?>
<div class="admin-title"><div><h1>Users</h1><p>Block or restore platform accounts.</p></div><form class="admin-search" method="get"><input name="q" value="<?= e($q) ?>" placeholder="Search name or email"><button>Search</button></form></div><section class="admin-panel table-wrap"><table class="admin-table"><thead><tr><th>User</th><th>Role</th><th>Department</th><th>Status</th><th>Joined</th><th>Action</th></tr></thead><tbody><?php foreach($users as $item): ?><tr><td><a href="<?= url('profile.php?id='.(int)$item['id']) ?>"><strong><?= e($item['name']) ?></strong><small><?= e($item['email']) ?></small></a></td><td><?= e(ucfirst($item['role'])) ?></td><td><?= e($item['department']?:'—') ?></td><td><span class="admin-status status-<?= e($item['status']) ?>"><?= e(ucfirst($item['status'])) ?></span></td><td><?= e(date('M d, Y',strtotime($item['created_at']))) ?></td><td><?php if($item['role']!=='admin'): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><input type="hidden" name="status" value="<?= $item['status']==='active'?'blocked':'active' ?>"><button class="<?= $item['status']==='active'?'danger':'success' ?>" data-confirm="Change this user status?"><?= $item['status']==='active'?'Block':'Unblock' ?></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></section>
<?php include __DIR__.'/_admin_footer.php'; ?>
